INSERT IGNORE INTO systems (system_id, name, description, position) VALUES ('fiscal', 'Conhecimento fiscal', 'O que é cada documento fiscal (NF-e, NFC-e, CT-e, MDF-e, CF-e) e para que serve.', 6);
INSERT IGNORE INTO modules (system_id, name, icon, position) VALUES ('fiscal', 'Documentos fiscais', 'receipt', 1);
INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'O que é uma nota fiscal (para que serve e como emitir)', 'Explicação geral sobre a nota fiscal: o que é, para que serve e como é emitida. Vídeo do canal Blog Abri Minha Empresa.', '9:42', '2023-06-29', 1, 'admin', 'youtube', 'rO9Jl1fDxpo', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fiscal' AND m.name = 'Documentos fiscais' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'rO9Jl1fDxpo');
INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'NFC-e: o que é a Nota Fiscal de Consumidor', 'O que é a NFC-e (nota fiscal de consumidor eletrônica) e quando ela é usada. Vídeo do canal TecnoSpeed.', '5:53', '2021-06-21', 2, 'admin', 'youtube', 'i_af_ZE47yE', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fiscal' AND m.name = 'Documentos fiscais' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'i_af_ZE47yE');
INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'CT-e: tudo o que você precisa saber', 'O que é o CT-e (Conhecimento de Transporte Eletrônico), documento obrigatório no transporte remunerado de cargas. Vídeo do canal Bsoft.', '6:39', '2020-08-31', 3, 'admin', 'youtube', 'paDzl5THXMc', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fiscal' AND m.name = 'Documentos fiscais' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'paDzl5THXMc');
INSERT IGNORE INTO user_module_access (user_id, module_id, created_at) SELECT u.user_id, m.module_id, NOW() FROM users u JOIN modules m ON m.system_id = 'fiscal' WHERE u.role = 'user' AND u.status = 'aprovado';
